struct CAIStateGroup_VersusEnemyBase_Methods : CAIStateGroup_VersusEnemyBase {
    CAIBrainCreature* GetPBrain() const { return *(CAIBrainCreature* const*)_pad_0x04; }   // PBrain (+0x04)
    CWorld* GetPWorld();                        // 0x008FCFC0
    void OnReplace();
